Below is a self‑contained Python script that meets all requirements and uses only the standard library:

```python
#!/usr/bin/env python3
import sys
import json
import time
import urllib.request
import urllib.error

URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"

def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    # Accept either a list or a dict containing "models"
    if isinstance(data, dict):
        if "models" in data:
            data = data["models"]
        elif "model" in data:
            data = [data["model"]]
        else:
            # fallback: use values if nothing obvious
            data = list(data.values())

    if not isinstance(data, list):
        raise ValueError("JSON must be a list or contain a 'models' key")

    models = []
    for item in data:
        if isinstance(item, str):
            models.append(item)
        elif isinstance(item, dict):
            if "id" in item:
                models.append(item["id"])
            elif "name" in item:
                models.append(item["name"])
            else:
                models.append(str(item))
        else:
            models.append(str(item))
    return models

def send_request(model, include_temperature=True):
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": 20,
    }
    if include_temperature:
        payload["temperature"] = 0

    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(URL, data=data, headers={"Content-Type": "application/json"})

    start = time.perf_counter()
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            body = resp.read().decode("utf-8", "replace")
            latency = time.perf_counter() - start
            return True, body, latency
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", "replace")
        latency = time.perf_counter() - start
        return False, body, latency
    except Exception as e:
        latency = time.perf_counter() - start
        return False, str(e), latency

def extract_content(body):
    try:
        data = json.loads(body)
    except Exception:
        return ""
    if isinstance(data, dict):
        choices = data.get("choices") or []
        if choices:
            choice = choices[0]
            if isinstance(choice, dict):
                msg = choice.get("message")
                if isinstance(msg, dict) and "content" in msg:
                    return msg["content"]
                if "text" in choice:
                    return choice["text"]
    return ""

def main():
    if len(sys.argv) != 2:
        print("Usage: python test_models.py models.json")
        sys.exit(1)

    models = load_models(sys.argv[1])
    results = []

    for model in models:
        ok, body, latency = send_request(model, include_temperature=True)

        # Retry without temperature if model doesn't support it
        if (not ok) and ("temperature" in body.lower() or "unsupported" in body.lower()):
            ok, body, latency = send_request(model, include_temperature=False)

        content = extract_content(body) if ok else ""
        if ok and content.strip():
            status = "PASS" if content.strip().startswith("OK") else "FAIL"
        else:
            status = "FAIL"

        response_text = (content if content else body).replace("\n", " ").strip()[:50]
        results.append((model, status, latency, response_text))

    # Table formatting
    model_w = max(len("Model"), max(len(r[0]) for r in results))
    status_w = max(len("Status"), max(len(r[1]) for r in results))
    latency_w = len("Latency")

    header = f"{'Model':<{model_w}}  {'Status':<{status_w}}  {'Latency':>{latency_w}}  Response"
    print(header)
    print("-" * len(header))

    ok_count = 0
    fail_count = 0

    for model, status, latency, resp in results:
        lat = f"{latency:.2f}s"
        print(f"{model:<{model_w}}  {status:<{status_w}}  {lat:>{latency_w}}  {resp}")
        if status == "PASS":
            ok_count += 1
        else:
            fail_count += 1

    print(f"Total: {len(results)} models | ✅ {ok_count} working | ❌ {fail_count} failed")

if __name__ == "__main__":
    main()
```

Usage:
```bash
python test_models.py models.json
```

This script:
- Loads models from a JSON file (list or `"models"` key)
- Sends the required prompt to each model
- Retries without `temperature` if unsupported
- Applies 30s timeout
- Captures latency, status, response
- Prints a formatted table and summary
